using System.ComponentModel.DataAnnotations;

namespace SkyShift.Application.DTOs;

/// <summary>
/// The Manager selects an unused catalog model; the server derives every
/// piece of vehicle metadata (manufacturer, model, road speed, seats,
/// descriptions, image path) from that catalog item. There are deliberately
/// no metadata properties here: any such JSON fields sent by an older client
/// are ignored by the deserializer and can never override catalog values.
/// The vehicle's own Id is still generated by the database.
/// </summary>
public class CreateVehicleRequest
{
    [Range(1, int.MaxValue, ErrorMessage = "CatalogItemId must reference a catalog model.")]
    public int CatalogItemId { get; set; }

    public bool IsPersonalExperimental { get; set; }
}
